/**
 * Multilingual UI strings. The bot interface is shown in the user's native
 * language (first: Ukrainian and Russian). NEVER hardcode user-facing text in
 * handlers — add a key here and resolve it via `t(lang, key)`.
 *
 * Note: these are *interface* strings. The Portuguese teaching content itself
 * is generated by the LLM, not stored here.
 */

export type UiLanguage = "uk" | "ru";

export const DEFAULT_LANGUAGE: UiLanguage = "uk";

export type StringKey =
  | "welcome"
  | "welcome_pick_language"
  | "menu_mode_words"
  | "menu_mode_sentences"
  | "menu_mode_conversation"
  | "help"
  | "not_implemented_yet"
  | "send_voice_hint"
  | "voice_menu_title"
  | "voice_changed"
  | "menu_mode_practice"
  | "practice_intro"
  | "practice_send_hint"
  | "practice_next_btn"
  | "practice_free_btn"
  | "practice_free_on"
  | "error_generic";

type Pack = Record<StringKey, string>;

