const packs: Record<UiLanguage, Pack> = { uk, ru };

export function t(lang: UiLanguage, key: StringKey): string {
  return packs[lang][key] ?? packs[DEFAULT_LANGUAGE][key];
}

export function isSupportedLanguage(value: string): value is UiLanguage {
  return value === "uk" || value === "ru";
}
